albums = FileAttachment("top_1000_albums.csv").csv({ typed: true })

// Extract primary genre
cleanAlbums = albums.map(d =&gt; ({
  ...d,
  primary_genre: d.genres ? d.genres.split(",")[0].trim() : "other"
}))

// Top genres list
topGenres = ["rock", "pop", "folk", "electronica", "punk", "hip-hop", "soul", "jazz", "country", "metal"]

// Select active genre
viewof activeGenre = Inputs.select(topGenres, {
  label: "Select Genre",
  value: "rock"
})

// Filter data for the active genre
genreAlbums = cleanAlbums.filter(d =&gt; d.primary_genre === activeGenre)

// Search within genre
viewof genreSearch = Inputs.search(genreAlbums, {
  placeholder: `Search within ${activeGenre}...`
})












































md`### Genre Overview: **${activeGenre.toUpperCase()}** (${genreSearch.length} albums)`







// Compute genre sonic profiles
genreSummary = topGenres.map(g =&gt; {
  const matching = cleanAlbums.filter(d =&gt; d.primary_genre === g);
  return {
    genre: g,
    count: matching.length,
    meanRating: d3.mean(matching, d =&gt; d.rating),
    meanYear: d3.mean(matching, d =&gt; d.year)
  };
})







// Abstract Genre Orbital Map: Average Era vs Average Rating, bubble size by album count
Plot.plot({
  width: width,
  height: 280,
  style: {
    background: "#121620",
    color: "#cbd5e1",
    borderRadius: "12px",
    padding: "1rem",
    border: "1px solid rgba(255, 255, 255, 0.08)"
  },
  x: { label: "Average Historical Era (Year) →", tickFormat: "" },
  y: { label: "Average Rating (⭐) →" },
  r: { range: [8, 30] },
  marks: [
    Plot.dot(
      genreSummary,
      {
        x: "meanYear",
        y: "meanRating",
        r: "count",
        fill: d =&gt; d.genre === activeGenre ? "#00f2fe" : "#2e3440",
        stroke: d =&gt; d.genre === activeGenre ? "#fff" : "rgba(255,255,255,0.25)",
        strokeWidth: 2,
        fillOpacity: 0.85,
        title: d =&gt; `${d.genre.toUpperCase()}\nAlbums: ${d.count}\nAvg Rating: ⭐ ${d.meanRating.toFixed(2)}\nHistorical Center: ${Math.round(d.meanYear)}`
      }
    ),
    Plot.text(genreSummary, {
      x: "meanYear",
      y: "meanRating",
      text: d =&gt; d.genre,
      dy: d =&gt; d.genre === activeGenre ? -18 : -14,
      fill: d =&gt; d.genre === activeGenre ? "#00f2fe" : "#94a3b8",
      fontWeight: "bold",
      fontSize: 11
    })
  ]
})







// Visual album cover grid for the genre
html`&lt;div class="album-grid"&gt;
  ${genreSearch.slice(0, 60).map(d =&gt; html`
    &lt;div class="album-card"&gt;
      &lt;div class="album-cover-wrap"&gt;
        &lt;img class="album-cover-img" src="${d.image_url}" alt="${d.album}" loading="lazy" /&gt;
        &lt;span class="album-badge"&gt;#${d.rank}&lt;/span&gt;
      &lt;/div&gt;
      &lt;div class="album-info"&gt;
        &lt;div class="album-title" title="${d.album}"&gt;${d.album}&lt;/div&gt;
        &lt;div class="album-artist" title="${d.artist}"&gt;${d.artist} (${d.year})&lt;/div&gt;
        &lt;div class="album-meta"&gt;
          &lt;span&gt;⭐ ${d.rating.toFixed(2)}&lt;/span&gt;
          &lt;span style="color: #00f2fe; text-transform: capitalize;"&gt;${d.primary_genre}&lt;/span&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  `)}
&lt;/div&gt;`

